
import { initDB, getConfig, setConfig, queryUser, queryUserByEmail, queryUserByEmailWithRetry } from './db.js';
import { ok, fail, json, getBody, getCookies, auditLog, setCookie, clearCookie, requireUser, requireAdmin } from './helpers.js';
import { encodeJwt, decodeJwt, verifySecret, hashSecret, genUuid, genTxId, genUserId, aesEncrypt, aesDecrypt, sha256Hex, nowMs } from './crypto.js';
import { setEnvSecrets } from './crypto.js';


// Inline frontend assets
const index_html = '';
const style_css = '';
const app_js = '';
const i18n_js = '';
const icons_js = '';
const disclaimer_js = '';

const FRONTEND_FILES = {
  html: index_html,
  css: style_css,
  app: app_js,
  i18n: i18n_js,
  icons: icons_js,
  disclaimer: disclaimer_js,
};

// ==================== CONSTANTS ====================
const ADMIN_USERNAME = 'admin';

// ==================== ROUTES ====================
export default {
  async fetch(request, env, ctx) {
    // Initialize secrets from environment
    if (env.JWT_SECRET_KEY && env.AES_ENCRYPTION_KEY) {
      setEnvSecrets(env.JWT_SECRET_KEY, env.AES_ENCRYPTION_KEY);
    }
    try {
      // CORS preflight
      if (request.method === 'OPTIONS') {
        return new Response(null, { status: 204, headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type,Authorization',
        }});
      }
      
      const url = new URL(request.url);
      const path = url.pathname;
      const db = env.DB;
      
      // Init DB on first request
      if (!env._init) {
        await initDB(db);
        env._init = true;
      }
      
      // Health check
      if (path === '/health') {
        return ok({ status: 'ok' });
      }
      
      // ==================== AUTH ROUTES ====================
      if (path.startsWith('/api/auth/')) {
        return handleAuth(request, db, env);
      }
      
      // ==================== ACCOUNTS ROUTES ====================
      if (path.startsWith('/api/accounts')) {
        return handleAccounts(request, db, env);
      }
      
      // ==================== CARDS ROUTES ====================
      if (path.startsWith('/api/cards')) {
        return handleCards(request, db, env);
      }
      
      // ==================== TRANSACTIONS ROUTES ====================
      if (path.startsWith('/api/transactions')) {
        return handleTransactions(request, db, env);
      }
      
      // ==================== SUBSCRIPTIONS ROUTES ====================
      if (path.startsWith('/api/subscriptions')) {
        return handleSubscriptions(request, db, env);
      }
      
      // ==================== GIFT CARDS ROUTES ====================
      if (path.startsWith('/api/giftcards')) {
        return handleGiftCards(request, db, env);
      }
      
      // ==================== FOREX ROUTES ====================
      if (path.startsWith('/api/forex')) {
        return handleForex(request, db, env);
      }
      
      // ==================== ESCROW ROUTES ====================
      if (path.startsWith('/api/escrow')) {
        return handleEscrow(request, db, env);
      }
      
      // ==================== SUGGESTIONS ROUTES ====================
      if (path.startsWith('/api/suggestions')) {
        return handleSuggestions(request, db, env);
      }
      if (path.startsWith('/api/admin/suggestions')) {
        return handleAdminSuggestions(request, db, env);
      }
      
      // ==================== CANCELLATION ROUTES ====================
      if (path.startsWith('/api/cancellations')) {
        return handleCancellations(request, db, env);
      }
      if (path.startsWith('/api/admin/cancellations')) {
        return handleAdminCancellations(request, db, env);
      }

      // ==================== KYC ROUTES ====================
      if (path.startsWith('/api/kyc')) {
        return handleKYC(request, db, env);
      }

      // ==================== SECRET TEST CHANNEL ====================
      // Secret access: Add ?dev_mode=true to URL to bypass KYC/verification
      if (url.searchParams.get('dev_mode') === 'true') {
        // Bypass authentication - return mock admin user
        const devUser = await requireUser(request, db);
        if (devUser) {
          devUser.isAdmin = true;
          devUser.is_verified = true; // Bypass KYC
          // Temporarily attach to request for downstream handlers
          request._devUser = devUser;
        }
      }

      // ==================== ADMIN ROUTES ====================
      if (path.startsWith('/api/admin/')) {
        return handleAdmin(request, db, env);
      }
      
      // Frontend SPA
      if (path === '/' || path === '/admin' || path.startsWith('/js/') || path.startsWith('/css/') || path === '/favicon.ico') {
        return serveFrontend(request, url, env);
      }
      
      return fail('Not found', 404);
    } catch (err) {
      console.error('[Worker Error]', err.message, err.stack);
      return new Response(JSON.stringify({ success: false, data: null, message: 'Internal server error: ' + err.message }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  }
};

// ==================== AUTH HANDLER ====================
async function handleAuth(request, db, env) {
  const url = new URL(request.url);
  const path = url.pathname;
  
  if (path === '/api/auth/register' && request.method === 'POST') {
    return authRegister(request, db);
  }
  if (path === '/api/auth/login' && request.method === 'POST') {
    return authLogin(request, db);
  }
  if (path === '/api/auth/logout' && request.method === 'POST') {
    const resp = ok({ message: 'Logged out' });
    await clearCookie(resp, 'access_token');
    return resp;
  }
  if (path === '/api/auth/refresh' && request.method === 'POST') {
    return authRefresh(request, db);
  }
  if (path === '/api/auth/me' && request.method === 'GET') {
    const user = await requireUser(request, db);
    if (!user) return fail('Not authenticated', 401);
    const accounts = await db.prepare(`SELECT id, name, type, currency FROM accounts WHERE user_id = ?`).bind(user.id).all();
    return ok({ user: userToPublic(user), accounts: accounts.results, settings: user.settings ? JSON.parse(user.settings) : {} });
  }
  if (path === '/api/auth/messages' && request.method === 'GET') {
    const user = await requireUser(request, db);
    if (!user) return fail('Not authenticated', 401);
    const box = user.message_box ? JSON.parse(user.message_box) : [];
    return ok({ messages: box });
  }
  if (path.startsWith('/api/auth/messages/') && request.method === 'PUT') {
    const mid = parseInt(path.split('/').pop());
    const user = await requireUser(request, db);
    if (!user) return fail('Not authenticated', 401);
    const box = user.message_box ? JSON.parse(user.message_box) : [];
    if (0 <= mid && mid < box.length) box[mid].read = true;
    await db.prepare(`UPDATE users SET message_box = ? WHERE id = ?`).bind(JSON.stringify(box), user.id).run();
    return ok({ message: 'ok' });
  }
  if (path === '/api/auth/devices' && request.method === 'GET') {
    const user = await requireUser(request, db);
    if (!user) return fail('Not authenticated', 401);
    return ok({ current_device: user.last_login_device, current_ip: user.last_login_ip });
  }
  if (path === '/api/auth/session' && request.method === 'DELETE') {
    const user = await requireUser(request, db);
    if (!user) return fail('Not authenticated', 401);
    const s = user.settings ? JSON.parse(user.settings) : {};
    s.session_version = (s.session_version || 0) + 1;
    await db.prepare(`UPDATE users SET settings = ? WHERE id = ?`).bind(JSON.stringify(s), user.id).run();
    return ok({ message: 'All devices signed out' });
  }
  return fail('Not found', 404);
}

// ==================== ACCOUNT HANDLER ====================
async function handleAccounts(request, db, env) {
  console.log('[handleAccounts] Starting...');
  const user = await requireUser(request, db);
  console.log('[handleAccounts] User:', user ? user.id : 'null');
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const url = new URL(request.url);
  const path = url.pathname;
  const method = request.method;
  console.log('[handleAccounts] Path:', path, 'Method:', method);

  // GET /api/accounts - list user's accounts
  if (path === '/api/accounts' && method === 'GET') {
    try {
      const accounts = await db.prepare(`SELECT * FROM accounts WHERE user_id = ? ORDER BY created_at DESC`).bind(user.id).all();
      console.log('[handleAccounts] Accounts query result:', accounts);
      const out = (accounts.results || []).map(a => ({
        id: a.id, name: a.name, type: a.type, currency: a.currency,
        created_at: a.created_at, is_active: a.is_active,
        iban: a.iban, swift_code: a.swift_code, country_code: a.country_code
      }));
      return ok({ accounts: out });
    } catch (err) {
      console.error('[handleAccounts] GET error:', err.message);
      throw err;
    }
  }
  
  // POST /api/accounts - create account
  if (path === '/api/accounts' && method === 'POST') {
    const d = await getBody(request);
    const name = (d.name || 'My Account').trim();
    const type = d.type || 'main';
    const currency = (d.currency || user.settings?.base_currency || 'CHF').toUpperCase();

    const id = genUuid();
    // Generate Swiss IBAN and SWIFT for main accounts
    const iban = type === 'main' ? generateIBAN() : null;
    const swiftCode = type === 'main' ? generateSWIFT() : null;
    await db.prepare(`INSERT INTO accounts (id, user_id, name, type, currency, created_at, is_active, iban, swift_code, iban_generated_at) VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?)`)
      .bind(id, user.id, name, type, currency, nowMs(), iban, swiftCode, nowMs()).run();

    return ok({ id, name, type, currency, iban, swift_code: swiftCode }, 'Account created');
  }
  // DELETE /api/accounts/:id - delete account
  if (path.startsWith('/api/accounts/') && method === 'DELETE') {
    const id = path.split('/').pop();
    const acc = await db.prepare(`SELECT * FROM accounts WHERE id = ? AND user_id = ?`).bind(id, user.id).first();
    if (!acc) return fail('Account not found', 404);

    // Check for active cards
    const cards = await db.prepare(`SELECT COUNT(*) as cnt FROM cards WHERE account_id = ?`).bind(acc.id).first();
    if (cards.cnt > 0) return fail('Cannot delete account with active cards');

    await db.prepare(`DELETE FROM accounts WHERE id = ?`).run(id);
    await auditLog(db, user.id, 'delete_account', id);
    return ok({}, 'Account deleted');
  }

  // GET /api/accounts/balances - get all card balances
  if (path === '/api/accounts/balances' && method === 'GET') {
    const accounts = await db.prepare(`SELECT * FROM accounts WHERE user_id = ?`).bind(user.id).all();
    const accountIds = (accounts.results || []).map(a => a.id);
    if (accountIds.length === 0) return ok({ balances: [] });

    const placeholder = accountIds.map(() => '?').join(',');
    const cards = await db.prepare(`SELECT * FROM cards WHERE account_id IN (${placeholder})`).bind(...accountIds).all();
    const out = (cards.results || []).map(c => ({
      account_id: c.account_id,
      card_id: c.id,
      card_number: maskCard(c.number),
      balance: round(c.balance),
      credit_limit: round(c.credit_limit),
      credit_used: round(c.credit_used),
      type: c.type,
      currency: accountIds.includes(c.account_id) ? 
        (accounts.results.find(a => a.id === c.account_id)?.currency || 'CHF') : 'CHF'
    }));
    return ok({ balances: out });
  }

  return fail('Not found', 404);
}

// ==================== CARD HANDLER ====================
async function handleCards(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const url = new URL(request.url);
  const path = url.pathname;
  const method = request.method;
  
  // GET /api/cards - list user's cards
  if (path === '/api/cards' && method === 'GET') {
    const cards = await db.prepare(`SELECT c.* FROM cards c JOIN accounts a ON c.account_id = a.id WHERE a.user_id = ? ORDER BY type, created_at`).bind(user.id).all();
    const out = (cards.results || []).map(c => buildCardResp(c));
    return ok({ cards: out });
  }
  
  // POST /api/cards - create card
  if (path === '/api/cards' && method === 'POST') {
    const d = await getBody(request);
    const type = d.type || 'debit';
    const network = d.network || 'NovaPay';
    const level = d.level || 'Standard';
    const theme = d.theme || 'starry';
    
    // Get or create main account
    let acc = await db.prepare(`SELECT id FROM accounts WHERE user_id = ? AND type = 'main' LIMIT 1`).bind(user.id).first();
    if (!acc) {
      const accId = genUuid();
      await db.prepare(`INSERT INTO accounts (id, user_id, name, type, currency, is_active) VALUES (?, ?, 'Main Account', 'main', ?, 1)`)
        .bind(accId, user.id, user.settings?.base_currency || 'CHF').run();
      acc = { id: accId };
    }
    
    const number = generateCardNumber();
    const cvv = String(Math.floor(100 + Math.random() * 900));
    const cvvHash = await sha256Hex(cvv);
    const expiry = '12/2030';
    
    const id = await db.prepare(`INSERT INTO cards (number, account_id, type, network, level, expiry, cvv_hash, status, balance, credit_limit, issued_at, last_used_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', 0, 50000, ?, ?)`)
      .bind(number, acc.id, type, network, level, expiry, cvvHash, nowMs(), null).lastInsertRowId;

    // Read back to avoid D1 async replication issues
    const insertedCard = await db.prepare(`SELECT * FROM cards WHERE id = ?`).bind(id).first();
    if (!insertedCard) return fail('Failed to create card', 500);

    const card = buildCardResp(insertedCard);
    await auditLog(db, user.id, 'create_card', number);
    return ok(card, 'Card created');
  }
  
  // GET /api/cards/:id - get card details
  if (path.startsWith('/api/cards/') && method === 'GET') {
    const id = path.split('/').pop();
    const card = await getOwnCard(db, user.id, parseInt(id));
    if (!card) return fail('Card not found', 404);
    return ok(buildCardResp(card));
  }

  // POST /api/cards/issue - issue new card (alias for POST /api/cards)
  if (path === '/api/cards/issue' && method === 'POST') {
    const d = await getBody(request);
    const type = d.type || 'debit';
    const network = d.network || 'NovaPay';
    const level = d.level || 'Standard';
    const theme = d.theme || 'starry';

    // Get or create main account
    const issueBase = (user.settings || {}).base_currency || 'CHF';
    let acc = await db.prepare(`SELECT id FROM accounts WHERE user_id = ? AND type = 'main' LIMIT 1`).bind(user.id).first();
    if (!acc) {
      const accId = genUuid();
      await db.prepare(`INSERT INTO accounts (id, user_id, name, type, currency, is_active) VALUES (?, ?, 'Main Account', 'main', ?, 1)`)
        .bind(accId, user.id, issueBase).run();
      acc = { id: accId };
    }

    // Find active debit card for payment
    const payer = await db.prepare(`SELECT id, balance FROM cards WHERE account_id = ? AND type = 'debit' AND status = 'active'`).bind(acc.id).first();

    // Check if this is the first debit card (free)
    const existingDebit = await db.prepare(`SELECT COUNT(*) as cnt FROM cards WHERE account_id = ? AND type = 'debit'`).bind(acc.id).first();
    const isFirstDebit = (existingDebit.cnt || 0) === 0;

    // Calculate and deduct fee (free for first debit card)
    const issueFee = isFirstDebit ? 0 : (issueBase === 'USD' ? 300 : 245);
    if (payer && !isFirstDebit && payer.balance < issueFee) return fail(`余额不足支付发卡费 ${issueFee} ${issueBase} / Insufficient balance`);

    if (!isFirstDebit && payer) {
      payer.balance -= issueFee;
      await db.prepare(`UPDATE cards SET balance = ? WHERE id = ?`).bind(payer.balance, payer.id).run();
    }

    const number = generateCardNumber();
    const cvv = String(Math.floor(100 + Math.random() * 900));
    const cvvHash = await sha256Hex(cvv);
    const expiry = type === 'debit' ? '12/2030' : '12/' + (new Date().getFullYear() + 5);

    const id = await db.prepare(`INSERT INTO cards (number, account_id, type, network, level, expiry, cvv_hash, status, balance, credit_limit, issued_at, last_used_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', 0, 50000, ?, ?)`)
      .bind(number, acc.id, type, network, level, expiry, cvvHash, nowMs(), null).lastInsertRowId;

    // Read back to avoid D1 async replication issues
    const insertedCard = await db.prepare(`SELECT * FROM cards WHERE id = ?`).bind(id).first();
    if (!insertedCard) return fail('Failed to issue card', 500);

    const card = buildCardResp(insertedCard);
    await auditLog(db, user.id, 'create_card', card.number_masked);
    return ok(card, 'Card issued');
  }

  // POST /api/cards/freeze - freeze card
  if (path === '/api/cards/freeze' && method === 'POST') {
    const d = await getBody(request);
    const cardId = d.card_id;
    const card = await getOwnCard(db, user.id, cardId);
    if (!card) return fail('Card not found', 404);
    if (card.status === 'frozen') return fail('Card already frozen');

    card.status = 'frozen';
    await db.prepare(`UPDATE cards SET status = ? WHERE id = ?`).bind('frozen', card.id).run();
    await auditLog(db, user.id, 'freeze_card', card.number);
    return ok({ status: 'frozen' }, 'Card frozen');
  }

  // POST /api/cards/unfreeze - unfreeze card
  if (path === '/api/cards/unfreeze' && method === 'POST') {
    const d = await getBody(request);
    const cardId = d.card_id;
    const card = await getOwnCard(db, user.id, cardId);
    if (!card) return fail('Card not found', 404);
    if (card.status !== 'frozen') return fail('Card not frozen');

    card.status = 'active';
    await db.prepare(`UPDATE cards SET status = ? WHERE id = ?`).bind('active', card.id).run();
    await auditLog(db, user.id, 'unfreeze_card', card.number);
    return ok({ status: 'active' }, 'Card unfrozen');
  }

  // POST /api/cards/renew - renew card (replace expired card)
  if (path === '/api/cards/renew' && method === 'POST') {
    const d = await getBody(request);
    const cardId = d.card_id;
    const card = await getOwnCard(db, user.id, cardId);
    if (!card) return fail('Card not found', 404);

    // Generate new card with same details but new number and expiry
    const newNumber = generateCardNumber();
    const newCvv = String(Math.floor(100 + Math.random() * 900));
    const newCvvHash = await sha256Hex(newCvv);
    const newExpiry = '12/' + (new Date().getFullYear() + 5);

    const newId = await db.prepare(`INSERT INTO cards (number, account_id, type, network, level, expiry, cvv_hash, status, balance, credit_limit, issued_at, last_used_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .bind(newNumber, card.account_id, card.type, card.network, card.level, newExpiry, newCvvHash, card.status, card.balance, card.credit_limit, nowMs(), card.last_used_at).lastInsertRowId;

    await auditLog(db, user.id, 'renew_card', newNumber);
    return ok({ id: newId, number: newNumber, expiry: newExpiry }, 'Card renewed');
  }

  // POST /api/cards/cancel - cancel card
  if (path === '/api/cards/cancel' && method === 'POST') {
    const d = await getBody(request);
    const cardId = d.card_id;
    const card = await getOwnCard(db, user.id, cardId);
    if (!card) return fail('Card not found', 404);

    // Transfer balance to escrow if debit card
    if (card.type === 'debit' && card.balance > 0) {
      const escrow = await db.prepare(`SELECT id, balance FROM escrow_pools WHERE user_id = ? AND currency = ?`).bind(user.id, card.account_id.currency).first();
      if (escrow) {
        await db.prepare(`UPDATE escrow_pools SET balance = balance + ? WHERE id = ?`).bind(card.balance, escrow.id).run();
      } else {
        await db.prepare(`INSERT INTO escrow_pools (user_id, currency, balance) VALUES (?, ?, ?)`).bind(user.id, card.account_id.currency, card.balance).run();
      }
    }

    card.status = 'cancelled';
    await db.prepare(`UPDATE cards SET status = 'cancelled' WHERE id = ?`).bind(card.id).run();
    await auditLog(db, user.id, 'cancel_card', card.number);
    return ok({ status: 'cancelled' }, 'Card cancelled');
  }

  // POST /api/cards/:id/reveal - reveal full card number and CVV
  if (path.match(/^\/api\/cards\/\d+\/reveal$/) && method === 'POST') {
    const id = parseInt(path.split('/')[3]);
    const d = await getBody(request);
    const card = await getOwnCard(db, user.id, id);
    if (!card) return fail('Card not found', 404);

    const validPin = await verifySecret(user.pin_hash, d.pin);
    if (!validPin) return fail('Wrong PIN', 400);

    // Return full card number and CVV for frontend display
    return ok({ number: card.number, cvv: d.cvv }, 'Revealed');
  }

  return fail('Not found', 404);
}

async function authRegister(request, db) {
  const d = await getBody(request);
  const email = (d.email || '').toLowerCase().trim();
  const name = (d.name || '').trim();
  const password = d.password || '';
  const pin = d.pin || '';
  
  if (!email || !email.includes('@')) return fail('Invalid email');
  if (password.length < 8) return fail('Password too short');
  if (!pin || !/^\d{4,}$/.test(pin)) return fail('PIN must be numeric');
  
  const existing = await queryUserByEmail(db, email);
  if (existing) return fail('Email already registered', 409);
  
  const uid = genUserId();
  const salt = Array.from(crypto.getRandomValues(new Uint8Array(16))).map(b => b.toString(16).padStart(2, '0')).join('');
  const passwordHash = await hashSecret(password);
  const pinHash = await hashSecret(pin);
  
  const accId = genUuid();
  await db.prepare(`INSERT INTO users (id, email, name, phone, id_number, dob, address, nationality, tax_jurisdiction, purpose, password_hash, pin_hash, salt, status, settings, message_box) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)`)
    .bind(uid, email, name || 'NovaPay User', d.phone || null, d.id_number || null, d.dob || null, d.address || null, d.nationality || null, d.tax_jurisdiction || null, d.purpose || 'Personal', passwordHash, pinHash, salt, JSON.stringify({ session_version: 0 }), JSON.stringify([])).run();
  
  await db.prepare(`INSERT INTO accounts (id, user_id, name, type, currency) VALUES (?, ?, ?, 'main', ?)`).bind(accId, uid, 'Main Account', d.currency || 'USD').run();
  
  await auditLog(db, uid, 'register', uid, {}, 'success');
  
  const token = await encodeJwt({ sub: uid, svf: 0 });
  const resp = ok({ user: uid, account: accId, settings: { session_version: 0 } }, 'Registered');
  await setCookie(resp, 'access_token', token);
  return resp;
}

async function authLogin(request, db) {
  const d = await getBody(request);
  const identifier = (d.identifier || '').trim();
  const password = d.password || '';

  // Query user with retry to handle D1 async replication lag
  let user = await queryUserByEmailWithRetry(db, identifier);
  if (!user) {
    // Also try querying by ID in case email lookup failed due to replication
    user = await queryUser(db, identifier);
  }

  // If still not found, try one more time with a longer delay
  if (!user) {
    await new Promise(resolve => setTimeout(resolve, 500));
    user = await queryUserByEmailWithRetry(db, identifier);
  }

  if (!user) return fail('Account not found', 401);
  
  const now = new Date();
  if (user.locked_until && new Date(user.locked_until) > now) {
    const remain = Math.ceil((new Date(user.locked_until) - now) / 60000);
    return fail(`Locked for ${remain} minutes`, 429);
  }
  
  const valid = await verifySecret(user.password_hash, password);
  if (!valid) {
    const failCount = (user.fail_count || 0) + 1;
    const maxAttempts = await getConfig(db, 'login_max_attempts', 5);
    if (failCount >= maxAttempts) {
      const duration = await getConfig(db, 'lock_duration_minutes', 15);
      await db.prepare(`UPDATE users SET fail_count = 0, locked_until = ? WHERE id = ?`).bind(new Date(Date.now() + duration * 60000).toISOString(), user.id).run();
    } else {
      await db.prepare(`UPDATE users SET fail_count = ? WHERE id = ?`).bind(failCount, user.id).run();
    }
    await auditLog(db, user.id, 'login', user.id, { status: 'failed' }, 'failed');
    return fail('Wrong password', 401);
  }
  
  await db.prepare(`UPDATE users SET fail_count = 0, locked_until = NULL, last_login_ip = ?, last_login_device = ? WHERE id = ?`).bind(identifier, request.headers.get('User-Agent') || '', user.id).run();

  const settings = user.settings ? JSON.parse(user.settings) : {};
  const token = await encodeJwt({ sub: user.id, svf: settings.session_version || 0 });
  const resp = ok({ user: user.id, two_fa_required: user.is_2fa_enabled, settings }, 'Logged in');
  await setCookie(resp, 'access_token', token);
  await auditLog(db, user.id, 'login', user.id, {}, 'success');
  return resp;
}

async function authRefresh(request, db) {
  const user = await requireUser(request, db);
  if (!user) return fail('Invalid session', 401);
  const settings = user.settings ? JSON.parse(user.settings) : {};
  const token = await encodeJwt({ sub: user.id, svf: settings.session_version || 0 });
  const resp = ok({}, 'Refreshed');
  await setCookie(resp, 'access_token', token);
  return resp;
}

function userToPublic(u) {
  return {
    id: u.id, email: u.email, name: u.name, phone: u.phone,
    nationality: u.nationality, tax_jurisdiction: u.tax_jurisdiction, purpose: u.purpose,
    status: u.status, created_at: u.created_at,
    credit_blacklist: toBool(u.credit_blacklist),
    is_2fa_enabled: toBool(u.is_2fa_enabled)
  };
}

// ==================== TRANSACTION HANDLER ====================
async function handleTransactions(request, db, env) {
  const url = new URL(request.url);
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const path = url.pathname;
  const method = request.method;
  
  if (path === '/api/transactions/topup' && method === 'POST') {
    const d = await getBody(request);
    const c = await getOwnCard(db, user.id, d.card_id);
    if (!c || c.type !== 'debit') return fail('Invalid debit card', 404);
    const amount = parseFloat(d.amount) || 0;
    if (amount <= 0) return fail('Amount > 0');
    c.balance += amount;
    await db.prepare(`UPDATE cards SET balance = ?, last_used_at = ? WHERE id = ?`).bind(c.balance, nowMs(), c.id).run();
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, type, amount, balance_after, status, created_at, ip_address, user_agent) VALUES (?, ?, ?, ?, 'topup', ?, ?, 'completed', ?, ?, ?)`)
      .bind(genTxId(), user.id, c.account_id, c.id, amount, round(c.balance), nowMs(), request.headers.get('CF-Connecting-IP') || '', request.headers.get('User-Agent') || '').run();
    return ok({ balance: round(c.balance), tx_id: '' }, 'Topped up');
  }
  
  if (path === '/api/transactions/transfer' && method === 'POST') {
    const d = await getBody(request);
    const src = await getOwnCard(db, user.id, d.from_card_id);
    if (!src || src.type !== 'debit') return fail('Invalid source card', 404);
    if (src.status !== 'active') return fail('Card not active', 400);
    
    const amount = parseFloat(d.amount) || 0;
    if (amount <= 0) return fail('Amount > 0');
    
    const validPin = await verifySecret(user.pin_hash, d.pin);
    if (!validPin) return fail('Wrong PIN', 400);
    
    if (amount > src.single_transaction_limit) return fail('Limit exceeded', 400);
    
    const base = ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    const feeRate = base === 'CHF' ? 0.003 : 0.005;
    const fee = round(amount * feeRate);
    const total = amount + fee;
    if (src.balance < total) return fail('Insufficient (incl. fee)', 400);
    
    const toNum = (d.to_card_number || '').replace(/\s/g, '');
    const dest = await db.prepare(`SELECT * FROM cards WHERE number = ?`).bind(toNum).first();
    if (!dest) return fail('Destination card not found', 404);
    
    src.balance -= total;
    await db.prepare(`UPDATE cards SET balance = ?, last_used_at = ? WHERE id = ?`).bind(src.balance, nowMs(), src.id).run();
    
    if (dest.type === 'debit') {
      dest.balance += amount;
      await db.prepare(`UPDATE cards SET balance = ? WHERE id = ?`).bind(dest.balance, dest.id).run();
    } else if (dest.type === 'credit') {
      dest.credit_used = Math.max(0, (dest.credit_used || 0) - amount);
      await db.prepare(`UPDATE cards SET credit_used = ? WHERE id = ?`).bind(dest.credit_used, dest.id).run();
    }
    
    const txOut = genTxId();
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, to_card_id, type, amount, fee, balance_after, status, created_at, ip_address, user_agent) VALUES (?, ?, ?, ?, ?, 'transfer_out', ?, ?, ?, 'completed', ?, ?, ?)`)
      .bind(txOut, user.id, src.account_id, src.id, dest.id, amount, fee, round(src.balance), nowMs(), request.headers.get('CF-Connecting-IP') || '', request.headers.get('User-Agent') || '').run();
    
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, to_card_id, type, amount, balance_after, status, created_at, ip_address, user_agent) VALUES (?, ?, ?, ?, ?, 'transfer_in', ?, ?, 'completed', ?, ?, ?)`)
      .bind(genTxId(), dest.user_id || user.id, dest.account_id, src.id, dest.id, amount, round(dest.balance || 0), nowMs(), request.headers.get('CF-Connecting-IP') || '', request.headers.get('User-Agent') || '').run();
    
    if (amount > 5000) {
      await pushMessage(db, user.id, `【Security Alert】Large transfer ${amount.toFixed(2)} ${base} detected.`);
    }

    // Fraud detection
    const baseCurrency = ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    if (amount > 10000) {
      const alertId = 'FRA' + nowMs();
      await db.prepare(`INSERT INTO fraud_alerts (id, user_id, alert_type, description, related_tx_id, amount, currency, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`)
        .bind(alertId, user.id, 'large_amount', `Large transfer ${amount.toFixed(2)} ${baseCurrency} exceeds threshold`, txOut, amount, baseCurrency, nowMs()).run();
      await db.prepare(`UPDATE transactions SET is_suspicious = 1 WHERE id = ?`).bind(txOut).run();
    }

    // Rapid-fire detection (check if user has >5 txns in last 5 min)
    const recentTxs = await db.prepare(`SELECT COUNT(*) as cnt FROM transactions WHERE user_id = ? AND created_at > ?`).bind(user.id, new Date(Date.now() - 300000).toISOString()).first();
    if (recentTxs.cnt >= 5) {
      const alertId = 'FRA' + nowMs();
      await db.prepare(`INSERT INTO fraud_alerts (id, user_id, alert_type, description, amount, currency, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)`)
        .bind(alertId, user.id, 'rapid_fire', `Rapid transfers detected: ${recentTxs.cnt} in 5 minutes`, amount, baseCurrency, nowMs()).run();
    }

    // First-time recipient detection
    const firstTransfer = await db.prepare(`SELECT COUNT(*) as cnt FROM transactions WHERE user_id = ? AND to_card_id = ? AND type = 'transfer_out'`).bind(user.id, dest.id).first();
    if (firstTransfer.cnt === 0) {
      const alertId = 'FRA' + nowMs();
      await db.prepare(`INSERT INTO fraud_alerts (id, user_id, alert_type, description, related_tx_id, amount, currency, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`)
        .bind(alertId, user.id, 'new_recipient', `First transfer to new card`, txOut, amount, baseCurrency, nowMs()).run();
    }
    
    return ok({ tx_id: txOut, fee, balance: round(src.balance) }, 'Transferred');
  }
  
  if (path === '/api/transactions/history' && method === 'GET') {
    const page = parseInt(url.searchParams.first('page')) || 1;
    const per = parseInt(url.searchParams.first('per_page')) || 20;
    const offset = (page - 1) * per;
    const txs = await db.prepare(`SELECT * FROM transactions WHERE user_id = ? ORDER BY created_at DESC LIMIT ? OFFSET ?`).bind(user.id, per, offset).all();
    const total = await db.prepare(`SELECT COUNT(*) as cnt FROM transactions WHERE user_id = ?`).bind(user.id).first();
    const out = (txs.results || []).map(t => ({
      id: t.id, type: t.type, amount: round(t.amount), fee: round(t.fee),
      status: t.status, is_suspicious: toBool(t.is_suspicious), created_at: t.created_at, category: t.category
    }));
    return ok({ transactions: out, page, per_page: per, total: total.cnt });
  }
  
  return fail('Not found', 404);
}

// ==================== SUBSCRIPTIONS HANDLER ====================
async function handleSubscriptions(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const path = new URL(request.url).pathname;
  const method = request.method;
  
  const SERVICE_CATALOG = [
    { brand: 'Netflix', plan_id: 'nf_std', plan_name: 'Standard', cycle: 'Monthly', amount: 15.99 },
    { brand: 'Spotify', plan_id: 'sp_prem', plan_name: 'Premium', cycle: 'Monthly', amount: 9.99 },
    { brand: 'Adobe', plan_id: 'ad_cc', plan_name: 'Creative Cloud', cycle: 'Yearly', amount: 599.88 },
    { brand: 'ChatGPT', plan_id: 'cg_plus', plan_name: 'Plus', cycle: 'Monthly', amount: 20.00 },
    { brand: 'iCloud', plan_id: 'ic_200', plan_name: '200GB', cycle: 'Monthly', amount: 2.99 },
  ];
  
  if (path === '/api/subscriptions/services' && method === 'GET') {
    return ok({ services: SERVICE_CATALOG });
  }
  
  if (path === '/api/subscriptions/bind-card' && method === 'POST') {
    const d = await getBody(request);
    const num = (d.card_number || '').replace(/\s/g, '');
    if (num.length < 13) return fail('Invalid card', 400);
    await db.prepare(`INSERT INTO bound_cards (user_id, card_number, masked, expiry, is_active) VALUES (?, ?, ?, ?, 1)`).bind(user.id, num, maskCard(num), d.expiry).run();
    return ok({ masked: maskCard(num) }, 'Card bound');
  }
  
  if (path === '/api/subscriptions/my-bound-cards' && method === 'GET') {
    const cards = await db.prepare(`SELECT * FROM bound_cards WHERE user_id = ? AND is_active = 1`).bind(user.id).all();
    return ok({ cards: (cards.results || []).map(c => ({ id: c.id, masked: c.masked, expiry: c.expiry, last4: c.card_number.slice(-4) })) });
  }
  
  if (path === '/api/subscriptions/subscribe' && method === 'POST') {
    const d = await getBody(request);
    const svc = SERVICE_CATALOG.find(s => s.plan_id === d.plan_id);
    if (!svc) return fail('Plan not found', 404);
    
    const main = await db.prepare(`SELECT id FROM accounts WHERE user_id = ? AND type = 'main'`).bind(user.id).first();
    if (!main) return fail('No main account');
    const pay = await db.prepare(`SELECT * FROM cards WHERE account_id = ? AND type = 'debit' AND status = 'active'`).bind(main.id).first();
    if (!pay || pay.balance < svc.amount) return fail('Insufficient balance', 400);
    
    pay.balance -= svc.amount;
    await db.prepare(`UPDATE cards SET balance = ? WHERE id = ?`).bind(pay.balance, pay.id).run();
    
    const subId = 'SUB' + nowMs().replace(/[-\s:]/g, '');
    await db.prepare(`INSERT INTO subscriptions (id, user_id, brand, plan_id, plan_name, cycle, amount, bound_card_number, start_date, next_billing_date, status, auto_renew) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', 1)`).bind(subId, user.id, svc.brand, svc.plan_id, svc.plan_name, svc.cycle, svc.amount, pay.number, nowMs(), new Date(Date.now() + 30*86400000).toISOString()).run();
    
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, type, amount, balance_after, status, created_at) VALUES (?, ?, ?, ?, 'subscription', ?, ?, 'completed', ?)`).bind(genTxId(), user.id, pay.account_id, pay.id, svc.amount, round(pay.balance), nowMs()).run();
    
    return ok({ subscription: { id: subId, brand: svc.brand, status: 'active' } }, 'Subscribed');
  }
  
  if (path === '/api/subscriptions/my' && method === 'GET') {
    const subs = await db.prepare(`SELECT * FROM subscriptions WHERE user_id = ?`).bind(user.id).all();
    return ok({ subscriptions: (subs.results || []).map(s => ({ id: s.id, brand: s.brand, plan_name: s.plan_name, cycle: s.cycle, amount: round(s.amount), status: s.status, auto_renew: toBool(s.auto_renew) })) });
  }
  
  if (path.match(/^\/api\/subscriptions\/[^\/]+$/) && method === 'DELETE') {
    const subId = path.split('/')[3];
    const sub = await db.prepare(`SELECT id FROM subscriptions WHERE id = ? AND user_id = ?`).bind(subId, user.id).first();
    if (!sub) return fail('Not found', 404);
    await db.prepare(`UPDATE subscriptions SET status = 'canceled', auto_renew = 0 WHERE id = ?`).bind(subId).run();
    return ok({}, 'Canceled');
  }
  
  return fail('Not found', 404);
}

// ==================== GIFT CARDS HANDLER ====================
async function handleGiftCards(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const path = new URL(request.url).pathname;
  const method = request.method;
  
  if (path === '/api/giftcards/buy' && method === 'POST') {
    const d = await getBody(request);
    const amount = parseFloat(d.amount) || 0;
    if (amount <= 0) return fail('Amount > 0');
    const feeRate = parseFloat(await getConfig(db, 'gift_card_fee_rate', 0.10));
    const fee = round(amount * feeRate);
    const main = await db.prepare(`SELECT id FROM accounts WHERE user_id = ? AND type = 'main'`).bind(user.id).first();
    if (!main) return fail('No main account', 404);
    const pay = await db.prepare(`SELECT id, balance FROM cards WHERE account_id = ? AND type = 'debit' AND status = 'active'`).bind(main.id).first();
    if (!pay || pay.balance < amount + fee) return fail('Insufficient balance');
    pay.balance -= (amount + fee);
    await db.prepare(`UPDATE cards SET balance = ? WHERE id = ?`).bind(pay.balance, pay.id).run();
    const code = generateGiftCode();
    await db.prepare(`INSERT INTO giftcards (code, amount, status, owner_user_id) VALUES (?, ?, 'active', ?)`).bind(code, amount, user.id).run();
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, type, amount, balance_after, status, created_at) VALUES (?, ?, ?, ?, 'giftcard_buy', ?, ?, 'completed', ?)`).bind(genTxId(), user.id, pay.account_id, pay.id, amount + fee, round(pay.balance), nowMs()).run();
    return ok({ code, amount, fee }, 'Purchased');
  }
  
  if (path === '/api/giftcards/redeem' && method === 'POST') {
    const d = await getBody(request);
    const code = (d.code || '').toUpperCase().trim();
    const gc = await db.prepare(`SELECT * FROM giftcards WHERE code = ?`).bind(code).first();
    if (!gc) return fail('Gift card not found', 404);
    if (gc.status !== 'active') return fail('Already used', 400);
    const c = await getOwnCard(db, user.id, d.card_id);
    if (!c || c.type !== 'debit') return fail('Invalid debit card', 404);
    c.balance += gc.amount;
    await db.prepare(`UPDATE cards SET balance = ? WHERE id = ?`).bind(c.balance, c.id).run();
    await db.prepare(`UPDATE giftcards SET status = 'used', redeemed_by_user_id = ?, redeemed_at = ? WHERE code = ?`).bind(user.id, nowMs(), code).run();
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, to_card_id, type, amount, balance_after, status, created_at) VALUES (?, ?, ?, ?, 'giftcard_redeem', ?, ?, 'completed', ?)`).bind(genTxId(), user.id, c.account_id, c.id, gc.amount, round(c.balance), nowMs()).run();
    return ok({ balance: round(c.balance) }, 'Redeemed');
  }
  
  if (path === '/api/giftcards/my' && method === 'GET') {
    const gcs = await db.prepare(`SELECT * FROM giftcards WHERE owner_user_id = ? ORDER BY created_at DESC`).bind(user.id).all();
    return ok({ giftcards: (gcs.results || []).map(g => ({ code: g.code, amount: round(g.amount), status: g.status, created_at: g.created_at })) });
  }
  
  if (path === '/api/giftcards/verify' && method === 'POST') {
    const d = await getBody(request);
    const gc = await db.prepare(`SELECT status, amount FROM giftcards WHERE code = ?`).bind((d.code || '').toUpperCase()).first();
    if (!gc) return ok({ valid: false, reason: 'not_found' });
    return ok({ valid: gc.status === 'active', amount: gc.amount, status: gc.status });
  }
  
  return fail('Not found', 404);
}

// ==================== FOREX HANDLER ====================
async function handleForex(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const url = new URL(request.url);
  const path = url.pathname;
  const method = request.method;
  
  const BASE_CURRENCIES = ['usd', 'eur', 'gbp', 'chf', 'jpy', 'cny', 'cad', 'aud', 'nzd', 'sgd', 'hkd', 'krw', 'inr', 'brl', 'rub', 'try', 'zar', 'mxn', 'sek', 'nok', 'dkk', 'pln', 'thb', 'idr', 'myr', 'php', 'czk', 'huf', 'ils', 'clp', 'arg', 'cop', 'pen', 'vnd'];
  
  if (path === '/api/forex/currencies' && method === 'GET') {
    return ok({ currencies: BASE_CURRENCIES.map(c => ({ code: c.toUpperCase(), name: c })) });
  }
  
  if (path === '/api/forex/rates' && method === 'GET') {
    const base = (url.searchParams.get('base') || 'CHF').toUpperCase();
    const rates = {};
    for (const cur of BASE_CURRENCIES) {
      if (cur === base.toLowerCase()) {
        rates[cur.toUpperCase()] = 1.0;
      } else {
        const rate = await fxLiveRate(cur, base);
        rates[cur.toUpperCase()] = rate;
      }
    }
    return ok({ base, rates, currencies: BASE_CURRENCIES.map(c => ({ code: c.toUpperCase(), name: c })) });
  }

  if (path === '/api/forex/history' && method === 'GET') {
    const from = (url.searchParams.get('from') || 'USD').toLowerCase();
    const to = (url.searchParams.get('to') || 'CHF').toLowerCase();
    const days = Math.min(180, Math.max(7, parseInt(url.searchParams.get('days')) || 30));
    const series = await fxHistory(from, to, days);
    return ok({ from: from.toUpperCase(), to: to.toUpperCase(), days, series });
  }
  
  if (path === '/api/forex/deposit' && method === 'POST') {
    const d = await getBody(request);
    const cardId = d.card_id;
    const fromC = (d.from_currency || 'USD').toUpperCase();
    const amount = parseFloat(d.amount) || 0;
    if (amount <= 0) return fail('Amount > 0');
    if (fromC === 'USD') return fail('Unsupported: use base currency');
    
    const c = await getOwnCard(db, user.id, cardId);
    if (!c || c.type !== 'debit') return fail('Invalid debit card', 404);
    
    const base = ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    const rate = fromC === base ? 1 : 1 / getFallbackRate(base.toLowerCase(), fromC.toLowerCase());
    const baseAmount = amount * rate;
    const depositFee = await getConfig(db, 'forex_deposit_fee', 0.05);
    const feeAmt = round(baseAmount * depositFee);
    const credited = round(baseAmount - feeAmt);
    
    c.balance += credited;
    await db.prepare(`UPDATE cards SET balance = ?, last_used_at = ? WHERE id = ?`).bind(c.balance, nowMs(), c.id).run();
    
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, type, amount, fee, balance_after, status, created_at, note) VALUES (?, ?, ?, ?, 'forex_deposit', ?, ?, ?, 'completed', ?, ?)`)
      .bind(genTxId(), user.id, c.account_id, c.id, amount, feeAmt, round(c.balance), nowMs(), `${fromC}→${base}`).run();
    
    return ok({ balance: round(c.balance), credited, fee: feeAmt, rate, base, from_currency: fromC }, 'Deposited');
  }
  
  if (path === '/api/forex/withdraw' && method === 'POST') {
    const d = await getBody(request);
    const cardId = d.card_id;
    const toC = (d.to_currency || 'USD').toUpperCase();
    const amount = parseFloat(d.amount) || 0;
    if (amount <= 0) return fail('Amount > 0');
    if (toC === 'USD') return fail('Unsupported: use base currency');
    
    const c = await getOwnCard(db, user.id, cardId);
    if (!c || c.type !== 'debit') return fail('Invalid debit card', 404);
    
    const base = ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    const rate = toC === base ? 1 : getFallbackRate(base.toLowerCase(), toC.toLowerCase());
    const withdrawFee = await getConfig(db, 'forex_withdraw_fee', 0.03);
    const feeAmt = round(amount * withdrawFee);
    const total = amount + feeAmt;
    
    if (c.balance < total) return fail('Insufficient balance');
    c.balance -= total;
    await db.prepare(`UPDATE cards SET balance = ?, last_used_at = ? WHERE id = ?`).bind(c.balance, nowMs(), c.id).run();
    
    const sent = round(amount * rate);
    await db.prepare(`INSERT INTO transactions (id, user_id, account_id, from_card_id, type, amount, fee, balance_after, status, created_at, note) VALUES (?, ?, ?, ?, 'forex_withdraw', ?, ?, ?, 'completed', ?, ?)`)
      .bind(genTxId(), user.id, c.account_id, c.id, amount, feeAmt, round(c.balance), nowMs(), `${base}→${toC}`).run();
    
    return ok({ balance: round(c.balance), sent, fee: feeAmt, rate, base, to_currency: toC }, 'Withdrawn');
  }
  
  return fail('Not found', 404);
}

// ==================== FX RATE CACHE ====================
const FX_CACHE = new Map();
const FX_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function fxLiveRate(from, to) {
  const key = `${from}:${to}`;
  const now = Date.now();
  const cached = FX_CACHE.first(key);
  if (cached && now - cached.time < FX_CACHE_TTL) {
    return cached.rate;
  }
  try {
    const resp = await fetch(`https://api.frankfurter.app/latest?from=${from.toUpperCase()}&to=${to.toUpperCase()}`);
    const data = await resp.json();
    const rate = data.rates?.[to.toUpperCase()] || getFallbackRate(from, to);
    FX_CACHE.set(key, { rate, time: now });
    return rate;
  } catch (e) {
    console.warn('[FX] Frankfurter API failed, using fallback:', e.message);
    return getFallbackRate(from, to);
  }
}

async function fxHistory(from, to, days) {
  const key = `hist:${from}:${to}:${days}`;
  const now = Date.now();
  const cached = FX_CACHE.first(key);
  if (cached && now - cached.time < FX_CACHE_TTL) {
    return cached.series;
  }
  try {
    const end = new Date();
    const start = new Date(end.getTime() - days * 86400000);
    const startDate = start.toISOString().slice(0, 10);
    const endDate = end.toISOString().slice(0, 10);
    const resp = await fetch(`https://api.frankfurter.app/${startDate}..${endDate}?from=${from.toUpperCase()}&to=${to.toUpperCase()}`);
    const data = await resp.json();
    const series = [];
    if (data.rates) {
      for (const [date, rates] of Object.entries(data.rates)) {
        if (rates[to.toUpperCase()]) {
          series.push({ date, rate: rates[to.toUpperCase()] });
        }
      }
    }
    if (series.length === 0) {
      // 使用几何布朗运动生成更真实的汇率历史
      const baseRate = getFallbackRate(from, to);
      // 不同货币对的波动率（年化）
      const volatility = {
        'usd': { 'eur': 0.08, 'gbp': 0.10, 'chf': 0.09, 'jpy': 0.12, 'cny': 0.06, 'cad': 0.07, 'aud': 0.09, 'nzd': 0.10, 'sgd': 0.06, 'hkd': 0.03, 'krw': 0.11, 'inr': 0.08, 'brl': 0.15, 'rub': 0.20, 'try': 0.25, 'zar': 0.12, 'mxn': 0.10, 'sek': 0.09, 'nok': 0.10, 'dkk': 0.05, 'pln': 0.11, 'thb': 0.08, 'idr': 0.12, 'myr': 0.07, 'php': 0.09, 'czk': 0.10, 'huf': 0.11, 'ils': 0.08, 'clp': 0.14, 'arg': 0.35, 'cop': 0.13, 'pen': 0.07, 'vnd': 0.05 },
        'eur': { 'usd': 0.08, 'gbp': 0.09, 'chf': 0.07, 'jpy': 0.11, 'cny': 0.07, 'cad': 0.08, 'aud': 0.10, 'nzd': 0.11, 'sgd': 0.07, 'hkd': 0.04, 'krw': 0.12, 'inr': 0.09, 'brl': 0.16, 'rub': 0.21, 'try': 0.26, 'zar': 0.13, 'mxn': 0.11, 'sek': 0.10, 'nok': 0.11, 'dkk': 0.04, 'pln': 0.12, 'thb': 0.09, 'idr': 0.13, 'myr': 0.08, 'php': 0.10, 'czk': 0.11, 'huf': 0.12, 'ils': 0.09, 'clp': 0.15, 'arg': 0.36, 'cop': 0.14, 'pen': 0.08, 'vnd': 0.06 },
        'gbp': { 'usd': 0.10, 'eur': 0.09, 'chf': 0.08, 'jpy': 0.13, 'cny': 0.09, 'cad': 0.10, 'aud': 0.12, 'nzd': 0.13, 'sgd': 0.09, 'hkd': 0.05, 'krw': 0.14, 'inr': 0.11, 'brl': 0.18, 'rub': 0.23, 'try': 0.28, 'zar': 0.15, 'mxn': 0.13, 'sek': 0.12, 'nok': 0.13, 'dkk': 0.06, 'pln': 0.14, 'thb': 0.11, 'idr': 0.15, 'myr': 0.10, 'php': 0.12, 'czk': 0.13, 'huf': 0.14, 'ils': 0.11, 'clp': 0.17, 'arg': 0.38, 'cop': 0.16, 'pen': 0.10, 'vnd': 0.07 },
        'chf': { 'usd': 0.09, 'eur': 0.07, 'gbp': 0.08, 'jpy': 0.12, 'cny': 0.08, 'cad': 0.09, 'aud': 0.11, 'nzd': 0.12, 'sgd': 0.08, 'hkd': 0.04, 'krw': 0.13, 'inr': 0.10, 'brl': 0.17, 'rub': 0.22, 'try': 0.27, 'zar': 0.14, 'mxn': 0.12, 'sek': 0.11, 'nok': 0.12, 'dkk': 0.05, 'pln': 0.13, 'thb': 0.10, 'idr': 0.14, 'myr': 0.09, 'php': 0.11, 'czk': 0.12, 'huf': 0.13, 'ils': 0.10, 'clp': 0.16, 'arg': 0.37, 'cop': 0.15, 'pen': 0.09, 'vnd': 0.06 }
      };
      const vol = (volatility[from]?.[to] || 0.10) * Math.sqrt(1/252); // 日波动率
      let rate = baseRate;
      const drift = 0; // 无漂移
      for (let i = days - 1; i >= 0; i--) {
        const d = new Date(end.getTime() - i * 86400000);
        const date = d.toISOString().slice(0, 10);
        // 使用 Box-Muller 变换生成正态分布随机数
        const u1 = Math.random() || 1e-10;
        const u2 = Math.random();
        const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
        rate = rate * Math.exp((drift - 0.5 * vol * vol) + vol * z);
        // 限制在合理范围内
        rate = Math.max(rate * 0.5, Math.min(rate * 1.5, rate));
        series.push({ date, rate: parseFloat(rate.toFixed(6)) });
      }
    }
    FX_CACHE.set(key, { series, time: now });
    return series;
  } catch (e) {
    console.warn('[FX] History API failed, using fallback:', e.message);
    const baseRate = getFallbackRate(from, to);
    const series = [];
    for (let i = days - 1; i >= 0; i--) {
      const d = new Date(end.getTime() - i * 86400000);
      const date = d.toISOString().slice(0, 10);
      const variation = (Math.random() - 0.5) * baseRate * 0.002;
      series.push({ date, rate: baseRate + variation });
    }
    return series;
  }
}

