// ==================== ESCROW HANDLER ====================
async function handleEscrow(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const url = new URL(request.url);
  const path = url.pathname;
  const method = request.method;
  const POOL_LIMITS = { CHF: 50000, USD: 50000 };
  
  if (path === '/api/escrow/pool' && method === 'GET') {
    const pools = await db.prepare(`SELECT * FROM escrow_pools WHERE user_id = ?`).bind(user.id).all();
    const base = ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    const out = {};
    for (const p of pools.results || []) out[p.currency] = { balance: round(p.balance), limit: p.limit_per_currency };
    for (const [cur, limit] of Object.entries(POOL_LIMITS)) {
      if (!out[cur]) out[cur] = { balance: 0, limit };
    }
    return ok({ pools: out });
  }
  
  if (path === '/api/escrow/deposit' && method === 'POST') {
    const d = await getBody(request);
    const amount = parseFloat(d.amount) || 0;
    const target = (d.target_currency || '').toUpperCase() || ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    if (amount <= 0) return fail('Amount > 0');
    if (!POOL_LIMITS[target]) return fail('Unsupported currency');
    
    const fee = amount * 0.08;
    const credited = amount - fee;
    const pool = await db.prepare(`SELECT id, balance FROM escrow_pools WHERE user_id = ? AND currency = ?`).bind(user.id, target).first();
    const existing = pool?.balance || 0;
    if (existing + credited > POOL_LIMITS[target]) return fail('Exceeds pool limit');
    
    if (pool) {
      await db.prepare(`UPDATE escrow_pools SET balance = balance + ? WHERE id = ?`).bind(credited, pool.id).run();
    } else {
      await db.prepare(`INSERT INTO escrow_pools (user_id, currency, balance) VALUES (?, ?, ?)`).bind(user.id, target, credited).run();
    }
    return ok({ currency: target, credited: round(credited), fee: round(fee), pool_balance: round(existing + credited), limit: POOL_LIMITS[target] }, 'Deposited');
  }
  
  if (path === '/api/escrow/withdraw' && method === 'POST') {
    const d = await getBody(request);
    const amount = parseFloat(d.amount) || 0;
    const target = (d.target_currency || '').toUpperCase() || ((user.settings || {}).base_currency || 'CHF').toUpperCase();
    if (amount <= 0) return fail('Amount > 0');
    if (!POOL_LIMITS[target]) return fail('Unsupported currency');
    
    const pool = await db.prepare(`SELECT id, balance FROM escrow_pools WHERE user_id = ? AND currency = ?`).bind(user.id, target).first();
    if (!pool || pool.balance < amount) return fail('Insufficient escrow balance');
    
    const fee = amount * 0.05;
    const net = amount - fee;
    await db.prepare(`UPDATE escrow_pools SET balance = balance - ? WHERE id = ?`).bind(amount, pool.id).run();
    
    return ok({ currency: target, sent: round(net), fee: round(fee), pool_balance: round(pool.balance - amount) }, 'Withdrawn');
  }
  
  return fail('Not found', 404);
}

// ==================== SUGGESTIONS HANDLER ====================
async function handleSuggestions(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const path = new URL(request.url).pathname;
  const method = request.method;
  
  if (path === '/api/suggestions' && method === 'POST') {
    const d = await getBody(request);
    const content = (d.content || '').trim();
    if (!content) return fail('Content required');
    const encrypted = await aesEncrypt(content);
    const digest = await sha256Hex(content);
    await db.prepare(`INSERT INTO suggestions (user_id, is_anonymous, content, content_encrypted, content_hash, status) VALUES (?, ?, ?, ?, ?, 'pending')`).bind(user.id, d.anonymous ? 1 : 0, content, encrypted, digest).run();
    return ok({ status: 'pending' }, 'Submitted');
  }
  
  if (path === '/api/suggestions/my' && method === 'GET') {
    const sugs = await db.prepare(`SELECT id, is_anonymous, preview, status, admin_action, submitted_at FROM (SELECT id, is_anonymous, substr(content, 1, 30) as preview, status, admin_action, submitted_at FROM suggestions WHERE user_id = ? ORDER BY submitted_at DESC) ORDER BY submitted_at DESC`).bind(user.id).all();
    return ok({ suggestions: (sugs.results || []).map(s => ({ id: s.id, is_anonymous: toBool(s.is_anonymous), preview: s.preview, status: s.status, admin_action: s.admin_action, submitted_at: s.submitted_at })) });
  }
  
  return fail('Not found', 404);
}

async function handleAdminSuggestions(request, db, env) {
  const admin = await requireAdmin(request, db);
  if (!admin) return fail('Admin required', 403);
  
  const path = new URL(request.url).pathname;
  const method = request.method;
  
  if (path === '/api/admin/suggestions' && method === 'GET') {
    const sugs = await db.prepare(`SELECT * FROM suggestions ORDER BY submitted_at DESC LIMIT 100`).all();
    return ok({ suggestions: (sugs.results || []).map(s => ({ id: s.id, submitted_at: s.submitted_at, is_anonymous: toBool(s.is_anonymous), status: s.status, admin_action: s.admin_action })) });
  }
  
  if (path.match(/^\/api\/admin\/suggestions\/\d+\/archive$/) && method === 'POST') {
    const sugId = parseInt(path.split('/')[4]);
    await db.prepare(`UPDATE suggestions SET status = 'archived', admin_action = 'archive', reviewed_by = ? WHERE id = ?`).bind(admin, sugId).run();
    return ok({}, 'Archived');
  }
  
  if (path.match(/^\/api\/admin\/suggestions\/\d+$/) && method === 'DELETE') {
    const sugId = parseInt(path.split('/')[4]);
    await db.prepare(`DELETE FROM suggestions WHERE id = ?`).run(sugId);
    return ok({}, 'Deleted');
  }
  
  return fail('Not found', 404);
}

// ==================== CANCELLATION HANDLERS ====================
async function handleCancellations(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);
  
  const path = new URL(request.url).pathname;
  const method = request.method;
  
  if (path === '/api/cancellations' && method === 'POST') {
    const d = await getBody(request);
    const reason = (d.reason || '').trim();
    if (!reason) return fail('Reason required');
    const encrypted = await aesEncrypt(reason);
    const digest = await sha256Hex(reason);
    await db.prepare(`INSERT INTO account_cancellations (user_id, reason, reason_encrypted, reason_hash, status) VALUES (?, ?, ?, ?, 'pending')`).bind(user.id, reason, encrypted, digest).run();
    return ok({ status: 'pending' }, 'Submitted');
  }
  
  if (path === '/api/cancellations/my' && method === 'GET') {
    const reqs = await db.prepare(`SELECT * FROM account_cancellations WHERE user_id = ? ORDER BY submitted_at DESC`).bind(user.id).all();
    return ok({ requests: (reqs.results || []).map(r => ({ id: r.id, reason_preview: (r.reason || '').slice(0, 40), status: r.status, admin_action: r.admin_action, submitted_at: r.submitted_at })) });
  }
  
  if (path.match(/^\/api\/cancellations\/\d+\/cancel$/) && method === 'POST') {
    const reqId = parseInt(path.split('/')[3]);
    await db.prepare(`UPDATE account_cancellations SET status = 'cancelled', admin_action = 'cancelled_by_user' WHERE id = ? AND user_id = ?`).bind(reqId, user.id).run();
    return ok({}, 'Cancelled');
  }
  
  return fail('Not found', 404);
}

async function handleAdminCancellations(request, db, env) {
  const admin = await requireAdmin(request, db);
  if (!admin) return fail('Admin required', 403);
  
  const path = new URL(request.url).pathname;
  const method = request.method;
  
  if (path === '/api/admin/cancellations' && method === 'GET') {
    const reqs = await db.prepare(`SELECT * FROM account_cancellations ORDER BY submitted_at DESC LIMIT 100`).all();
    return ok({ requests: (reqs.results || []).map(r => ({ id: r.id, user_id: r.user_id, status: r.status, admin_action: r.admin_action, submitted_at: r.submitted_at })) });
  }
  
  if (path.match(/^\/api\/admin\/cancellations\/\d+\/approve$/) && method === 'POST') {
    const reqId = parseInt(path.split('/')[4]);
    const r = await db.prepare(`SELECT * FROM account_cancellations WHERE id = ?`).bind(reqId).first();
    if (!r || r.status !== 'pending') return fail('Invalid request', 400);
    
    // Transfer card balances to escrow
    const base = 'CHF';
    const accounts = await db.prepare(`SELECT id FROM accounts WHERE user_id = ?`).bind(r.user_id).all();
    for (const acc of accounts.results || []) {
      const cards = await db.prepare(`SELECT id, balance FROM cards WHERE account_id = ? AND type = 'debit' AND balance > 0`).bind(acc.id).all();
      for (const card of cards.results || []) {
        let pool = await db.prepare(`SELECT id, balance FROM escrow_pools WHERE user_id = ? AND currency = ?`).bind(r.user_id, base).first();
        if (pool) {
          await db.prepare(`UPDATE escrow_pools SET balance = balance + ? WHERE id = ?`).bind(card.balance, pool.id).run();
        } else {
          await db.prepare(`INSERT INTO escrow_pools (user_id, currency, balance) VALUES (?, ?, ?)`).bind(r.user_id, base, card.balance).run();
        }
        await db.prepare(`UPDATE cards SET balance = 0, status = 'canceled' WHERE id = ?`).bind(card.id).run();
      }
    }
    
    await db.prepare(`UPDATE users SET status = 'closed' WHERE id = ?`).bind(r.user_id).run();
    await db.prepare(`UPDATE account_cancellations SET status = 'approved', admin_action = 'approved', admin_note = ?, reviewed_by = ?, reviewed_at = ? WHERE id = ?`).bind((r.admin_note || '') + ` [Approved by ${admin}]`, admin, nowMs(), reqId).run();
    
    return ok({}, 'Account closed');
  }
  
  if (path.match(/^\/api\/admin\/cancellations\/\d+\/reject$/) && method === 'POST') {
    const reqId = parseInt(path.split('/')[4]);
    const d = await getBody(request);
    await db.prepare(`UPDATE account_cancellations SET status = 'rejected', admin_action = 'rejected', admin_note = ?, reviewed_by = ?, reviewed_at = ? WHERE id = ?`).bind(d.note || '', admin, nowMs(), reqId).run();
    return ok({}, 'Rejected');
  }
  
  return fail('Not found', 404);
}

// ==================== KYC HANDLERS ====================
async function handleKYC(request, db, env) {
  const user = await requireUser(request, db);
  if (!user) return fail('Not authenticated', 401);
  if (user._blocked) return fail(user._blocked, 403);

  const path = new URL(request.url).pathname;
  const method = request.method;

  // GET /api/kyc/my - get user's KYC status
  if (path === '/api/kyc/my' && method === 'GET') {
    const docs = await db.prepare(`SELECT * FROM kyc_documents WHERE user_id = ? ORDER BY submitted_at DESC`).bind(user.id).all();
    const documentList = (docs.results || []).map(d => ({
      id: d.id, type: d.document_type, status: d.status, submitted_at: d.submitted_at
    }));
    // Check if user has completed KYC (at least one approved document)
    const hasApproved = documentList.some(d => d.status === 'approved');
    return ok({ documents: documentList, is_verified: hasApproved });
  }

  // POST /api/kyc/upload - upload KYC document
  if (path === '/api/kyc/upload' && method === 'POST') {
    const d = await getBody(request);
    const docType = d.type || 'passport';
    const docUrl = d.url || '';
    if (!docUrl) return fail('Document URL required');

    await db.prepare(`INSERT INTO kyc_documents (user_id, document_type, document_url, status, submitted_at) VALUES (?, ?, ?, 'pending', ?)`)
      .bind(user.id, docType, docUrl, nowMs()).run();
    return ok({ status: 'pending' }, 'Document uploaded, pending review');
  }

  // POST /api/kyc/verify - verify all documents (admin or test bypass)
  if (path === '/api/kyc/verify' && method === 'POST') {
    const d = await getBody(request);
    const force = d.force || false;
    if (!force && !user.isAdmin) return fail('Admin only', 403);

    await db.prepare(`UPDATE kyc_documents SET status = 'approved', reviewed_at = ?, reviewed_by = ? WHERE user_id = ? AND status = 'pending'`)
      .bind(nowMs(), user.id, user.id).run();
    return ok({}, 'All KYC documents verified');
  }

  return fail('Not found', 404);
}

// ==================== ADMIN HANDLER ====================
async function handleAdmin(request, db, env) {
  const url = new URL(request.url);
  const path = url.pathname;
  const method = request.method;
  
  if (path === '/api/admin/login' && method === 'POST') {
    const d = await getBody(request);
    const username = (d.username || '').trim();
    const password = d.password || '';
    if (!process.env?.ADMIN_PASSWORD_HASH) return fail('Admin not configured', 500);
    if (username !== ADMIN_USERNAME || !(await verifySecret(process.env.ADMIN_PASSWORD_HASH, password))) {
      return fail('Invalid credentials', 401);
    }
    const token = await encodeJwt({ sub: ADMIN_USERNAME, role: 'admin' });
    const resp = ok({}, 'Logged in');
    await setCookie(resp, 'admin_token', token);
    return resp;
  }
  
  if (path === '/api/admin/logout' && method === 'POST') {
    const resp = ok({}, 'Logged out');
    await clearCookie(resp, 'admin_token');
    return resp;
  }
  
  const admin = await requireAdmin(request, db);
  if (!admin) return fail('Admin required', 403);
  
  // Dashboard
  if (path === '/api/admin/dashboard' && method === 'GET') {
    const totalUsers = (await db.prepare(`SELECT COUNT(*) as cnt FROM users`).first()).cnt;
    const activeUsers = (await db.prepare(`SELECT COUNT(*) as cnt FROM users WHERE status = 'active'`).first()).cnt;
    const bannedUsers = (await db.prepare(`SELECT COUNT(*) as cnt FROM users WHERE status IN ('suspended', 'blacklisted', 'closed')`).first()).cnt;
    const totalCards = (await db.prepare(`SELECT COUNT(*) as cnt FROM cards`).first()).cnt;
    const frozenCards = (await db.prepare(`SELECT COUNT(*) as cnt FROM cards WHERE status = 'frozen'`).first()).cnt;
    const today = new Date().toISOString().slice(0, 10);
    const txToday = await db.prepare(`SELECT SUM(amount) as sum FROM transactions WHERE created_at LIKE ?`).bind(`${today}%`).all();
    return ok({
      total_users: totalUsers, active_users: activeUsers, banned_users: bannedUsers,
      total_cards: totalCards, frozen_cards: frozenCards,
      tx_today: round(txToday.sum || 0)
    });
  }
  
  // Users
  if (path === '/api/admin/users' && method === 'GET') {
    const users = await db.prepare(`SELECT id, email, name, status, created_at, credit_blacklist FROM users ORDER BY created_at DESC`).all();
    return ok({ users: users.results?.map(u => ({ ...u, credit_blacklist: toBool(u.credit_blacklist) })) || [] });
  }
  
  if (path.match(/^\/api\/admin\/users\/[^\/]+\/ban$/) && method === 'POST') {
    const uid = path.split('/')[4];
    await db.prepare(`UPDATE users SET status = 'suspended' WHERE id = ?`).run(uid);
    return ok({}, 'Banned');
  }
  
  if (path.match(/^\/api\/admin\/users\/[^\/]+\/unban$/) && method === 'POST') {
    const uid = path.split('/')[4];
    await db.prepare(`UPDATE users SET status = 'active' WHERE id = ?`).run(uid);
    return ok({}, 'Unbanned');
  }
  
  if (path.match(/^\/api\/admin\/users\/[^\/]+\/blacklist$/) && method === 'POST') {
    const uid = path.split('/')[4];
    await db.prepare(`UPDATE users SET credit_blacklist = 1 WHERE id = ?`).run(uid);
    return ok({}, 'Blacklisted');
  }
  
  if (path.match(/^\/api\/admin\/users\/[^\/]+\/unblacklist$/) && method === 'POST') {
    const uid = path.split('/')[4];
    await db.prepare(`UPDATE users SET credit_blacklist = 0 WHERE id = ?`).run(uid);
    return ok({}, 'Unblacklisted');
  }
  
  if (path.match(/^\/api\/admin\/users\/[^\/]+$/) && method === 'DELETE') {
    const uid = path.split('/')[4];
    const confirm = (await getBody(request)).confirm;
    if (!confirm) return fail('Confirmation required', 400);
    await db.prepare(`DELETE FROM users WHERE id = ?`).run(uid);
    return ok({}, 'User deleted');
  }
  
  // Cards
  if (path === '/api/admin/cards' && method === 'GET') {
    const cards = await db.prepare(`SELECT * FROM cards ORDER BY issued_at DESC LIMIT 100`).all();
    return ok({ cards: (cards.results || []).map(c => ({
      id: c.id, number_masked: maskCard(c.number), type: c.type, network: c.network,
      level: c.level, status: c.status, balance: round(c.balance), credit_limit: round(c.credit_limit),
      credit_used: round(c.credit_used), issued_at: c.issued_at
    })) });
  }
  
  if (path.match(/^\/api\/admin\/cards\/\d+\/freeze$/) && method === 'POST') {
    const cardId = parseInt(path.split('/')[4]);
    await db.prepare(`UPDATE cards SET status = 'frozen' WHERE id = ?`).run(cardId);
    return ok({}, 'Frozen');
  }
  
  if (path.match(/^\/api\/admin\/cards\/\d+\/unfreeze$/) && method === 'POST') {
    const cardId = parseInt(path.split('/')[4]);
    await db.prepare(`UPDATE cards SET status = 'active' WHERE id = ?`).run(cardId);
    return ok({}, 'Unfrozen');
  }
  
  if (path.match(/^\/api\/admin\/cards\/\d+\/cancel$/) && method === 'POST') {
    const cardId = parseInt(path.split('/')[4]);
    await db.prepare(`UPDATE cards SET status = 'canceled' WHERE id = ?`).run(cardId);
    return ok({}, 'Canceled');
  }
  
  if (path.match(/^\/api\/admin\/cards\/\d+\/restore$/) && method === 'POST') {
    const cardId = parseInt(path.split('/')[4]);
    await db.prepare(`UPDATE cards SET status = 'active' WHERE id = ? AND status = 'canceled'`).run(cardId);
    return ok({}, 'Restored');
  }
  
  // Config
  if (path === '/api/admin/config' && method === 'GET') {
    return ok({ config: await getAllConfigs(db) });
  }
  
  if (path === '/api/admin/config' && method === 'PUT') {
    const d = await getBody(request);
    for (const [key, value] of Object.entries(d)) {
      await setConfig(db, key, value, admin);
    }
    return ok({}, 'Config updated');
  }

  // User detail
  if (path.match(/^\/api\/admin\/users\/[^\/]+$/) && method === 'GET') {
    const uid = path.split('/')[4];
    const user = await queryUser(db, uid);
    if (!user) return fail('User not found', 404);
    const accounts = await db.prepare(`SELECT * FROM accounts WHERE user_id = ?`).bind(uid).all();
    const accountIds = (accounts.results || []).map(a => a.id);
    const cards = await db.prepare(`SELECT * FROM cards WHERE account_id IN (${accountIds.map(() => '?').join(',')})`).bind(...accountIds).all();
    const subs = await db.prepare(`SELECT * FROM subscriptions WHERE user_id = ?`).bind(uid).all();
    return ok({
      user: { id: user.id, email: user.email, name: user.name, status: user.status, credit_blacklist: toBool(user.credit_blacklist), created_at: user.created_at },
      accounts: (accounts.results || []).map(a => ({
        id: a.id, name: a.name, type: a.type, currency: a.currency,
        iban: a.iban, swift_code: a.swift_code,
        cards: (cards.results || []).filter(c => c.account_id === a.id).map(c => ({
          number_masked: maskCard(c.number), level: c.level, status: c.status, balance: round(c.balance)
        }))
      })),
      subscriptions: (subs.results || []).map(s => ({ brand: s.brand, plan_name: s.plan_name, status: s.status }))
    });
  }

  // Reset user password
  if (path.match(/^\/api\/admin\/users\/[^\/]+\/reset-password$/) && method === 'POST') {
    const uid = path.split('/')[4];
    const d = await getBody(request);
    const newPw = (d.new_password || '').trim();
    if (newPw.length < 8) return fail('Password too short', 400);
    const newHash = await hashSecret(newPw);
    await db.prepare(`UPDATE users SET password_hash = ? WHERE id = ?`).bind(newHash, uid).run();
    await auditLog(db, admin, 'reset_password', uid, {}, 'success');
    return ok({}, 'Password reset');
  }

  // All transactions (admin)
  if (path === '/api/admin/transactions' && method === 'GET') {
    const page = parseInt(url.searchParams.first('page')) || 1;
    const per = Math.min(100, parseInt(url.searchParams.first('per_page')) || 50);
    const offset = (page - 1) * per;
    const total = await db.prepare(`SELECT COUNT(*) as cnt FROM transactions`).first();
    const txs = await db.prepare(`SELECT * FROM transactions ORDER BY created_at DESC LIMIT ? OFFSET ?`).bind(per, offset).all();
    return ok({
      transactions: (txs.results || []).map(t => ({
        id: t.id, user_id: t.user_id, type: t.type, amount: round(t.amount), fee: round(t.fee),
        status: t.status, is_suspicious: toBool(t.is_suspicious), category: t.category,
        from_card: t.from_card_id, to_card: t.to_card_id, created_at: t.created_at
      })),
      page, per_page: per, total: total.cnt
    });
  }

  // Audit logs (admin)
  if (path === '/api/admin/audit-logs' && method === 'GET') {
    const page = parseInt(url.searchParams.first('page')) || 1;
    const per = Math.min(200, parseInt(url.searchParams.first('per_page')) || 50);
    const offset = (page - 1) * per;
    const total = await db.prepare(`SELECT COUNT(*) as cnt FROM audit_logs`).first();
    const logs = await db.prepare(`SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT ? OFFSET ?`).bind(per, offset).all();
    return ok({ logs: (logs.results || []).map(l => ({
      id: l.id, user_id: l.user_id, action: l.action, target: l.target,
      details: l.details, status: l.status, created_at: l.created_at
    })), page, per_page: per, total: total.cnt });
  }

  // Fraud alerts (admin)
  if (path === '/api/admin/fraud-alerts' && method === 'GET') {
    const resolved = url.searchParams.first('resolved');
    let q = `SELECT * FROM fraud_alerts ORDER BY created_at DESC LIMIT 200`;
    if (resolved === '0') q += ` WHERE resolved = 0`;
    else if (resolved === '1') q += ` WHERE resolved = 1`;
    const alerts = await db.prepare(q).all();
    return ok({ alerts: (alerts.results || []).map(a => ({
      id: a.id, user_id: a.user_id, alert_type: a.alert_type,
      description: a.description, related_tx_id: a.related_tx_id,
      amount: round(a.amount), currency: a.currency,
      resolved: toBool(a.resolved), resolved_at: a.resolved_at,
      resolved_by: a.resolved_by, created_at: a.created_at
    })) });
  }

  // Resolve fraud alert
  if (path.match(/^\/api\/admin\/fraud-alerts\/\d+\/resolve$/) && method === 'POST') {
    const alertId = path.split('/')[4];
    await db.prepare(`UPDATE fraud_alerts SET resolved = 1, resolved_at = ?, resolved_by = ? WHERE id = ?`).bind(nowMs(), admin, alertId).run();
    return ok({}, 'Resolved');
  }

  // KYC documents (admin)
  if (path === '/api/admin/kyc' && method === 'GET') {
    const pending = await db.prepare(`SELECT * FROM kyc_documents WHERE status = 'pending' ORDER BY submitted_at DESC LIMIT 50`).all();
    const recent = await db.prepare(`SELECT * FROM kyc_documents ORDER BY submitted_at DESC LIMIT 100`).all();
    return ok({
      pending: (pending.results || []).map(d => ({ id: d.id, user_id: d.user_id, type: d.document_type, url: d.document_url, submitted_at: d.submitted_at })),
      all: (recent.results || []).map(d => ({ id: d.id, user_id: d.user_id, type: d.document_type, status: d.status, submitted_at: d.submitted_at }))
    });
  }

  // Approve KYC document
  if (path.match(/^\/api\/admin\/kyc\/\d+\/approve$/) && method === 'POST') {
    const docId = parseInt(path.split('/')[4]);
    await db.prepare(`UPDATE kyc_documents SET status = 'approved', reviewed_at = ?, reviewed_by = ? WHERE id = ?`).bind(nowMs(), admin, docId).run();
    return ok({}, 'Approved');
  }

  // Reject KYC document
  if (path.match(/^\/api\/admin\/kyc\/\d+\/reject$/) && method === 'POST') {
    const docId = parseInt(path.split('/')[4]);
    const d = await getBody(request);
    await db.prepare(`UPDATE kyc_documents SET status = 'rejected', reviewed_at = ?, reviewed_by = ?, rejection_reason = ? WHERE id = ?`).bind(nowMs(), admin, d.reason || '', docId).run();
    return ok({}, 'Rejected');
  }

  return fail('Not found', 404);
}

// ==================== UTILITY FUNCTIONS ====================

function generateGiftCode(length = 16) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < length; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code.replace(/(.{4})/g, '$1-').slice(0, -1);
}

async function pushMessage(db, userId, text) {
  const user = await queryUser(db, userId);
  if (!user) return;
  const box = user.message_box ? JSON.parse(user.message_box) : [];
  box.unshift({ text, time: nowMs(), read: false });
  if (box.length > 20) box.length = 20;
  await db.prepare(`UPDATE users SET message_box = ? WHERE id = ?`).bind(JSON.stringify(box), userId).run();
}

// Generate Swiss IBAN (CH93 XXXX XXXXX XXXXX XXXXX X)
function generateIBAN(userCountry = 'CH') {
  const bankCode = String(Math.floor(Math.random() * 900) + 100);
  const accountNum = String(Math.floor(Math.random() * 99999)).padStart(7, '0');
  const checkDigits = '93';
  const full = bankCode + '00' + accountNum + checkDigits;
  // Mod-97 check
  let remainder = 0;
  for (let i = 0; i < full.length; i++) {
    remainder = (remainder * 10 + parseInt(full[i])) % 97;
  }
  const newCheck = String(98 - remainder).padStart(2, '0');
  return userCountry.toUpperCase() + newCheck + bankCode + '00' + accountNum;
}

// Generate SWIFT/BIC code
function generateSWIFT() {
  const banks = ['UBSW', 'CRES', 'ZABA', 'UBS', 'CSFB', 'BAHZ', 'EZEB', 'MATT'];
  const bank = banks[Math.floor(Math.random() * banks.length)];
  const country = 'CH';
  const location = String.fromCharCode(65 + Math.floor(Math.random() * 26)) +
                    String.fromCharCode(65 + Math.floor(Math.random() * 26));
  const branch = Math.random() > 0.7 ?
    String.fromCharCode(65 + Math.floor(Math.random() * 26)) +
    String.fromCharCode(65 + Math.floor(Math.random() * 26)) : '';
  return bank + country + location + branch;
}

function round(n) {
  return Math.round((n + Number.EPSILON) * 100) / 100;
}

function maskCard(number) {
  if (!number || number.length < 4) return '****';
  return '**** **** **** ' + number.slice(-4);
}

async function getOwnCard(db, userId, cardId) {
  return await db.prepare(`
    SELECT c.*, a.user_id FROM cards c
    JOIN accounts a ON c.account_id = a.id
    WHERE c.id = ? AND a.user_id = ?
  `).bind(cardId, userId).first();
}

function generateCardNumber(length = 16, network = 'NovaPay') {
  const binRanges = {
    'Visa': ['4'],
    'MasterCard': ['51', '52', '53', '54', '55', '2221', '2222', '2223', '2224', '2225', '2226', '2227', '2228', '2229', '223', '224', '225', '226', '227', '228', '229', '23', '24', '25', '26', '270', '271', '272', '2720'],
    'AmericanExpress': ['34', '37'],
    'NovaPay': ['4', '5', '6', '9']
  };
  const prefixList = binRanges[network] || binRanges['NovaPay'];
  const prefix = prefixList[Math.floor(Math.random() * prefixList.length)];
  const prefixLen = prefix.length;
  const bodyLen = length - prefixLen - 1;
  let body = '';
  for (let i = 0; i < bodyLen; i++) body += Math.floor(Math.random() * 10);
  let partial = prefix + body;
  let total = 0;
  const flipParity = (partial.length % 2 === 1);
  for (let i = 0; i < partial.length; i++) {
    const d = parseInt(partial[i]);
    let pos = partial.length - 1 - i;
    if (flipParity) pos = 15 - pos;
    if (pos % 2 === 1) {
      const doubled = d * 2;
      total += doubled > 9 ? doubled - 9 : doubled;
    } else {
      total += d;
    }
  }
  const check = (10 - (total % 10)) % 10;
  return partial + check;
}

function buildCardResp(c) {
  return {
    id: c.id, number_masked: maskCard(c.number), type: c.type, network: c.network,
    level: c.level, expiry: c.expiry, status: c.status, theme: c.theme,
    balance: round(c.balance), credit_limit: round(c.credit_limit),
    credit_used: round(c.credit_used), daily_limit: c.daily_limit,
    single_transaction_limit: c.single_transaction_limit, issued_at: c.issued_at
  };
}

async function serveFrontend(request, url, env) {
  // For SPA routing, return index.html or the appropriate static file
  const path = url.pathname.startsWith('/') ? url.pathname.slice(1) : url.pathname;
  // Root path is '' after slice — treat as .html for content-type resolution
  const resolvedPath = path || 'index.html';
  const ext = resolvedPath.slice(resolvedPath.lastIndexOf('.'));

  // Map file paths to FRONTEND_FILES keys
  let fileKey = null;
  if (path === 'index.html' || path === '') {
    fileKey = 'html';
  } else if (path.startsWith('js/') && path.endsWith('.js')) {
    fileKey = path.replace('js/', '').replace('.js', '');
    // Map common filenames
    const jsMap = { 'app': 'app', 'i18n': 'i18n', 'icons': 'icons', 'disclaimer': 'disclaimer' };
    fileKey = jsMap[fileKey] || fileKey;
  } else if (path.startsWith('css/') && path.endsWith('.css')) {
    fileKey = path.replace('css/', '').replace('.css', '');
    const cssMap = { 'style': 'css' };
    fileKey = cssMap[fileKey] || fileKey;
  } else if (path === 'favicon.ico') {
    fileKey = null; // No favicon in bundle
  }

  const contentType = {
    '.html': 'text/html; charset=utf-8',
    '.js': 'application/javascript; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.ico': 'image/x-icon',
  }[ext] || 'application/octet-stream';

  const content = fileKey ? FRONTEND_FILES[fileKey] : null;
  if (content) {
    // Properly decode UTF-8 from base64 (strip whitespace/newlines)
    const clean = content.replace(/\s/g, '');
    const bytes = new Uint8Array(atob(clean).split('').map(c => c.charCodeAt(0)));
    const decoded = new TextDecoder('utf-8').decode(bytes);
    return new Response(decoded, {
      status: 200,
      headers: { 'Content-Type': contentType }
    });
  }

  // SPA fallback - return index.html for any non-API route
  if (url.pathname === '/' || url.pathname === '/admin' ||
      url.pathname.startsWith('/js/') || url.pathname.startsWith('/css/') ||
      url.pathname === '/favicon.ico') {
    const clean = FRONTEND_FILES['html'].replace(/\s/g, '');
    const bytes = new Uint8Array(atob(clean).split('').map(c => c.charCodeAt(0)));
    const decoded = new TextDecoder('utf-8').decode(bytes);
    return new Response(decoded, {
      status: 200,
      headers: { 'Content-Type': 'text/html; charset=utf-8' }
    });
  }

  return new Response('Not found', { status: 404 });
}
